changeSet.sql:
DROP INDEX google_health.idx_google_health_heart_rate_fingerprint;
DROP INDEX google_health.idx_google_health_data_point_fingerprint;
DROP INDEX google_health.uq_google_health_heart_rate_identity;
CREATE UNIQUE INDEX uq_google_health_heart_rate_identity
    ON google_health.heart_rate_sample(connection_id,identity_key)
    WHERE COALESCE(google_resource_name ~ '^users/[^/]+/dataTypes/heart-rate/dataPoints/[^/]+$',false);
CREATE UNIQUE INDEX uq_google_health_heart_rate_time_identity
    ON google_health.heart_rate_sample(connection_id,sample_time,identity_key)
    WHERE NOT COALESCE(google_resource_name ~ '^users/[^/]+/dataTypes/heart-rate/dataPoints/[^/]+$',false);
